def orbit(r,c):
    seen={(r,c)}; todo=[(r,c)]
    while todo:
        a,b=todo.pop()
        cand=[(b,a),(31-a,b),(b,31-a),(31-b,a)]
        for p in cand:
            if 0<=p[0]<30 and 0<=p[1]<30 and p not in seen:
                seen.add(p);todo.append(p)
    return seen
holes=[(r,c) for r in range(30) for c in range(30) if grid[r][c]==6]
len(holes), [(p, sorted({grid[a][b] for a,b in orbit(*p) if grid[a][b]!=6}), sorted(orbit(*p))) for p in holes if not any(grid[a][b]!=6 for a,b in orbit(*p))][:4]

orbits=[]; seen=set(); bad=[]
for p in holes:
 if p in seen: continue
 o=orbit(*p); seen |= o
 vals={grid[a][b] for a,b in o if grid[a][b]!=6}
 if len(vals)>1: bad.append((p,vals,[(q,grid[q[0]][q[1]]) for q in o if grid[q[0]][q[1]]!=6]))
 orbits.append((p,o,vals))
len(orbits),len(bad),bad[:2]

out=[row[:] for row in grid]
for r,c in holes:
 vals={grid[a][b] for a,b in orbit(r,c) if grid[a][b]!=6}
 assert len(vals)==1
 out[r][c]=vals.pop()
print('\n'.join(' '.join(map(str,row)) for row in out))
